#!/bin/bash
# Update v2.3.0 release notes in Persian
set -e
cd /home/z/my-project
TOKEN=$(git config --get remote.origin.url | sed -n 's|https://[^:]*:\([^@]*\)@github.com.*|\1|p')
REPO="021hk/modiriat-hesab"
REL_ID=$(curl -s -H "Authorization: Bearer $TOKEN" "$REPO/releases/tags/v2.3.0" | grep -oP '"id": \K[0-9]+' | head -1)
[ -z "$REL_ID" ] && REL_ID=$(curl -s -H "Authorization: Bearer $TOKEN" "https://api.github.com/repos/$REPO/releases/tags/v2.3.0" | grep -oP '"id": \K[0-9]+' | head -1)
echo "release id: $REL_ID"

cat > /tmp/release-v230.json <<'EOF'
{
  "name": "حساب‌یار نسخه ۲.۳.۰ — اندروید",
  "body": "## دانلود برنامه اندروید (APK)\n\nفایل **hesab-yar-v2.3.0.apk** را از بخش Assets پایین همین صفحه دانلود و نصب کنید.\n\n## تغییرات مهم این نسخه — خواندن هوشمند پیامک\n\n### ۱) فقط شماره‌های تنظیم‌شده خوانده می‌شود\n- دیگر همه پیامک‌ها بررسی نمی‌شوند. در ویرایش هر حساب بانکی، **شماره فرستنده پیامک** آن بانک را وارد کنید (مثل `9999` یا `5000142`)\n- فقط پیامک‌های همان شماره‌ها پردازش می‌شوند؛ بقیه اصلاً نادیده گرفته می‌شوند\n- چند شماره را می‌توانید با کاما جدا کنید\n\n### ۲) تفکیک چند حساب در یک شماره\n- از یک شماره فرستنده ممکن است پیامک چند حساب مختلف برسد (مثلاً از ۱۰ پیامک، فقط ۵ تای آن مال حساب شماست)\n- برنامه **خط شماره حساب/کارت داخل پیامک** (که معمولاً نقطه دارد، مثل `777.888.13972872.1`) را می‌خواند و با شماره حساب/کارت ثبت‌شده شما تطبیق می‌دهد\n- پیامک‌های حساب‌های دیگر (مثلاً اعضای خانواده در همان بانک) **به‌طور خودکار رد می‌شوند** و دیگر به حساب شما اضافه نمی‌شوند\n- نتیجه بررسی پیامک‌ها حالا نشان می‌دهد چند پیامک «حساب دیگری» نادیده گرفته شد\n\n### ۳) تشخیص واریز / برداشت / خرید\n- هم با علامت مثبت/منفی (مثل `-473,000`) و هم با کلمات **واریز / برداشت / خرید** تشخیص داده می‌شود\n\n## روش نصب\n\n1. فایل APK را دانلود کنید\n2. روی فایل بزنید؛ اگر پرسید، اجازه «نصب از منابع ناشناس» را بدهید\n3. اولین بار که برنامه باز شود، دسترسی **پیامک (SMS)** را تأیید کنید\n4. وارد تب «بانک‌ها» شوید، حساب خود را ویرایش کنید و **شماره فرستنده پیامک** را وارد کنید — از این به بعد خواندن خودکار فعال است\n\n> توجه: اگر نسخه قبلی را نصب دارید، امضای نسخه‌ها یکسان است و می‌توانید مستقیم روی آن نصب کنید (داده‌های شما می‌ماند)."
}
EOF

curl -s -X PATCH -H "Authorization: Bearer $TOKEN" -H "Content-Type: application/json" \
  -d @/tmp/release-v230.json "https://api.github.com/repos/$REPO/releases/$REL_ID" | grep -oP '"name": "\K[^"]*' | head -1
echo "== assets =="
curl -s -H "Authorization: Bearer $TOKEN" "https://api.github.com/repos/$REPO/releases/$REL_ID/assets" | grep -oP '"name": "\K[^"]+|"size": \K[0-9]+' | head -4
